#include "valid-c-prefix-fopen.test.hpp"

// ADR-046: Valid c_ prefix with fopen and fgets while loop
// cppcheck-suppress misra-c2012-21.6
#include <stdio.h>

#include <string.h>

char line[257] = "";

void readFile(void) {
    FILE* c_file = fopen("data.txt", "r");
    if (c_file != nullptr) {
        const char* c_result = fgets(line, 257, c_file);
        while (c_result != nullptr) {
            static_cast<void>(printf("%s", line));
            c_result = fgets(line, 257, c_file);
        }
        static_cast<void>(fclose(c_file));
    }
}
